type_tests:
const total: number = totalPrice([{ price: 1, quantity: 1 }], 0);
// @ts-expect-error: the tax rate is a number, not a string
totalPrice([], "0.1");
// @ts-expect-error: every item needs a quantity
totalPrice([{ price: 1 }], 0);

